class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def sumK(self, root: TreeNode, K: int) -> int:
        MOD = 10**9 + 7
        prefix_count = {0: 1}
        total = 0
        current_sum = 0

        def dfs(node, curr):
            nonlocal total
            if not node:
                return

            curr += node.val

            target = curr - K
            if target in prefix_count:
                total = (total + prefix_count[target]) % MOD

            prefix_count[curr] = prefix_count.get(curr, 0) + 1

            dfs(node.left, curr)
            dfs(node.right, curr)

            prefix_count[curr] -= 1
            if prefix_count[curr] == 0:
                del prefix_count[curr]

        dfs(root, 0)
        return total
